  1→/* ── Design Tokens ────────────────────────────────────────
  2→ *  Pure CSS custom properties on :root.
  3→ *  Single source of truth for the entire design system.
  4→ *  OKLCH color space · 4 px spacing grid · variable fonts.
  5→ * ──────────────────────────────────────────────────────── */
  6→
  7→@layer tokens {
  8→  :root {
  9→    /* ── Base surfaces (dark → light) ─────────────────── */
 10→    --color-background: oklch(13% 0.008 250);
 11→    --color-card: oklch(18% 0.008 250);
 12→    --color-popover: oklch(22% 0.008 250);
 13→    --color-secondary: oklch(22% 0.008 250);
 14→    --color-muted: oklch(25% 0.008 250);
 15→
 16→    /* ── Borders & inputs ─────────────────────────────── */
 17→    --color-border: oklch(30% 0.010 250);
 18→    --color-input: oklch(30% 0.010 250);
 19→
 20→    /* ── Text ─────────────────────────────────────────── */
 21→    --color-foreground: oklch(92% 0 0);
 22→    --color-card-foreground: oklch(92% 0 0);
 23→    --color-popover-foreground: oklch(92% 0 0);
 24→    --color-secondary-foreground: oklch(85% 0 0);
 25→    --color-muted-foreground: oklch(55% 0.005 250);
 26→
 27→    /* ── Accent — steel blue ──────────────────────────── */
 28→    --color-primary: oklch(62% 0.10 245);
 29→    --color-primary-foreground: oklch(98% 0 0);
 30→    --color-accent: oklch(62% 0.10 245);
 31→    --color-accent-foreground: oklch(92% 0 0);
 32→    --color-ring: oklch(62% 0.10 245);
 33→
 34→    /* ── Semantic signals ─────────────────────────────── */
 35→    --color-destructive: oklch(55% 0.22 27);
 36→    --color-destructive-foreground: oklch(92% 0 0);
 37→    --color-warning: oklch(72% 0.17 70);
 38→    --color-warning-foreground: oklch(13% 0.008 250);
 39→    --color-success: oklch(62% 0.15 155);
 40→    --color-success-foreground: oklch(13% 0.008 250);
 41→    --color-info: oklch(70% 0.08 245);
 42→    --color-info-foreground: oklch(13% 0.008 250);
 43→
 44→    /* ── Map surfaces ──────────────────────────────────── */
 45→    --color-map-background: oklch(13% 0.008 250);
 46→    --color-map-land: oklch(15% 0.008 250);
 47→    --color-map-water: oklch(18% 0.04 245);
 48→    --color-map-roads: oklch(25% 0.008 250);
 49→    --color-map-buildings: oklch(22% 0.008 250);
 50→    --color-map-labels: var(--color-muted-foreground);
 51→
 52→    /* ── Spacing (4 px base grid) ─────────────────────── */
 53→    --spacing-xs: 0.25rem;
 54→    --spacing-sm: 0.5rem;
 55→    --spacing-md: 1rem;
 56→    --spacing-lg: 1.5rem;
 57→    --spacing-xl: 2rem;
 58→    --spacing-2xl: 3rem;
 59→
 60→    /* ── Typography ───────────────────────────────────── */
 61→    --font-sans: "Inter Variable", "Inter", system-ui, sans-serif;
 62→    --font-mono: "JetBrains Mono Variable", "JetBrains Mono", ui-monospace, monospace;
 63→    --font-size-xs: 0.75rem;
 64→    --font-size-xs--line-height: 1rem;
 65→    --font-size-sm: 0.875rem;
 66→    --font-size-sm--line-height: 1.25rem;
 67→    --font-size-base: 1rem;
 68→    --font-size-base--line-height: 1.5rem;
 69→    --font-size-lg: 1.125rem;
 70→    --font-size-lg--line-height: 1.75rem;
 71→    --font-size-xl: 1.25rem;
 72→    --font-size-xl--line-height: 1.75rem;
 73→    --font-size-2xl: 1.5rem;
 74→    --font-size-2xl--line-height: 2rem;
 75→    --font-size-3xl: 1.875rem;
 76→    --font-size-3xl--line-height: 2.25rem;
 77→    --font-size-4xl: 2.25rem;
 78→    --font-size-4xl--line-height: 2.5rem;
 79→    --font-size-5xl: 3rem;
 80→    --font-size-5xl--line-height: 1;
 81→    --font-size-6xl: 3.75rem;
 82→    --font-size-6xl--line-height: 1;
 83→
 84→    /* ── Container widths ─────────────────────────────── */
 85→    --container-xs: 20rem;
 86→    --container-sm: 24rem;
 87→    --container-md: 28rem;
 88→    --container-lg: 32rem;
 89→    --container-xl: 40rem;
 90→    --container-2xl: 48rem;
 91→    --container-3xl: 64rem;   /* 1024px */
 92→    --container-4xl: 80rem;   /* 1280px */
 93→    --container-5xl: 96rem;   /* 1536px */
 94→
 95→    /* ── Layout ─────────────────────────────────────────── */
 96→    --sidebar-width: 16rem;
 97→
 98→    /* ── Control heights ──────────────────────────────── */
 99→    --control-sm: 2rem;
100→    --control-md: 2.25rem;
101→    --control-lg: 2.5rem;
102→
103→    /* ── Border radius ────────────────────────────────── */
104→    --radius-sm: 2px;
105→    --radius-md: 4px;
106→    --radius-lg: 6px;
107→    --radius-full: 9999px;
108→
109→    /* ── Shadows (dark-UI tuned) ──────────────────────── */
110→    --shadow-sm: 0 1px 2px oklch(0% 0 0 / 30%);
111→    --shadow-md: 0 2px 6px oklch(0% 0 0 / 40%);
112→    --shadow-lg: 0 4px 12px oklch(0% 0 0 / 50%);
113→
114→    /* ── Glow + Glass (off by default) ───────────────── */
115→    --glow-strength: 0;
116→    --glass-strength: 0;
117→    --glow-color: oklch(62% 0.10 245);
118→    --glow-sm:      0 0 14px oklch(62% 0.10 245 / calc(0.5 * var(--glow-strength)));
119→    --glow-primary: 0 0 28px oklch(62% 0.10 245 / calc(0.75 * var(--glow-strength)));
120→    --glow-lg:      0 0 48px oklch(62% 0.10 245 / calc(1.0 * var(--glow-strength)));
121→    --glow-xl:      0 0 72px oklch(62% 0.10 245 / calc(0.6 * var(--glow-strength))),
122→                    0 0 120px oklch(62% 0.10 245 / calc(0.25 * var(--glow-strength)));
123→    --glass-bg:     oklch(100% 0 0 / calc(0.12 * var(--glass-strength)));
124→    --glass-border: oklch(100% 0 0 / calc(0.22 * var(--glass-strength)));
125→    --glass-blur:   calc(24px * var(--glass-strength));
126→    --glass-shadow: inset 0 1px 0 oklch(100% 0 0 / calc(0.12 * var(--glass-strength))),
127→                    0 0 20px oklch(62% 0.10 245 / calc(0.15 * var(--glow-strength)));
128→
129→    /* ── Motion ───────────────────────────────────────── */
130→    --duration-fast: 100ms;
131→    --duration-normal: 150ms;
132→    --duration-slow: 250ms;
133→    --duration-emphasis: 500ms;
134→    --duration-scenic: 800ms;
135→    --ease-default: cubic-bezier(0.25, 0.1, 0.25, 1);
136→    --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
137→    --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
138→    --ease-in-out-back: cubic-bezier(0.68, -0.6, 0.32, 1.6);
139→
140→    /* ── Z-index scale ────────────────────────────────── */
141→    --z-base: 0;
142→    --z-above: 10;
143→    --z-modal: 50;
144→    --z-toast: 100;
145→  }
146→
147→  /* ── Ocean theme ─────────────────────────────────────────
148→   *  Dark teal / slate palette with golden-yellow accent.
149→   *  Activate with data-theme="ocean" on <html> or any root.
150→   * ──────────────────────────────────────────────────────── */
151→  [data-theme="ocean"] {
152→    /* ── Base surfaces (dark → light) ─────────────────── */
153→    --color-background: oklch(16% 0.03 210);
154→    --color-card: oklch(21% 0.04 200);
155→    --color-popover: oklch(25% 0.04 200);
156→    --color-secondary: oklch(25% 0.04 200);
157→    --color-muted: oklch(30% 0.04 200);
158→
159→    /* ── Borders & inputs ─────────────────────────────── */
160→    --color-border: oklch(35% 0.03 200);
161→    --color-input: oklch(35% 0.03 200);
162→
163→    /* ── Text ─────────────────────────────────────────── */
164→    --color-foreground: oklch(90% 0 0);
165→    --color-card-foreground: oklch(90% 0 0);
166→    --color-popover-foreground: oklch(90% 0 0);
167→    --color-secondary-foreground: oklch(82% 0 0);
168→    --color-muted-foreground: oklch(55% 0.01 200);
169→
170→    /* ── Accent — golden yellow ──────────────────────── */
171→    --color-primary: oklch(78% 0.15 85);
172→    --color-primary-foreground: oklch(15% 0.02 85);
173→    --color-accent: oklch(78% 0.15 85);
174→    --color-accent-foreground: oklch(15% 0.02 85);
175→    --color-ring: oklch(78% 0.15 85);
176→
177→    /* ── Glow color (theme-matched) ──────────────────── */
178→    --glow-color: oklch(78% 0.15 85);
179→    --glow-sm:      0 0 14px oklch(78% 0.15 85 / calc(0.5 * var(--glow-strength)));
180→    --glow-primary: 0 0 28px oklch(78% 0.15 85 / calc(0.75 * var(--glow-strength)));
181→    --glow-lg:      0 0 48px oklch(78% 0.15 85 / calc(1.0 * var(--glow-strength)));
182→    --glow-xl:      0 0 72px oklch(78% 0.15 85 / calc(0.6 * var(--glow-strength))),
183→                    0 0 120px oklch(78% 0.15 85 / calc(0.25 * var(--glow-strength)));
184→    --glass-shadow: inset 0 1px 0 oklch(100% 0 0 / calc(0.12 * var(--glass-strength))),
185→                    0 0 20px oklch(78% 0.15 85 / calc(0.15 * var(--glow-strength)));
186→
187→    /* ── Semantic signals ─────────────────────────────── */
188→    --color-destructive: oklch(55% 0.22 27);
189→    --color-destructive-foreground: oklch(92% 0 0);
190→    --color-warning: oklch(72% 0.17 70);
191→    --color-warning-foreground: oklch(15% 0.02 85);
192→    --color-success: oklch(62% 0.15 155);
193→    --color-success-foreground: oklch(15% 0.02 85);
194→    --color-info: oklch(68% 0.08 210);
195→    --color-info-foreground: oklch(15% 0.02 85);
196→
197→    /* ── Map surfaces ─────────────────────────────────── */
198→    --color-map-background: oklch(16% 0.03 210);
199→    --color-map-land: oklch(19% 0.03 200);
200→    --color-map-water: oklch(22% 0.06 210);
201→    --color-map-roads: oklch(30% 0.03 200);
202→    --color-map-buildings: oklch(25% 0.04 200);
203→    --color-map-labels: var(--color-muted-foreground);
204→  }
205→
206→  /* ── Effects toggle — explicit override ─────────────────
207→   *  data-effects="glow-glass" → force on (e.g. base theme)
208→   *  data-effects="none"       → force off (e.g. TFC opt-out)
209→   * ──────────────────────────────────────────────────────── */
210→  [data-effects="glow-glass"] {
211→    --glow-strength: 1;
212→    --glass-strength: 1;
213→  }
214→
215→  [data-effects="none"] {
216→    --glow-strength: 0;
217→    --glass-strength: 0;
218→  }
219→
220→  @media (prefers-reduced-motion: reduce) {
221→    :root {
222→      --duration-fast: 0ms;
223→      --duration-normal: 0ms;
224→      --duration-slow: 0ms;
225→      --glow-strength: 0;
226→      --glass-strength: 0;
227→    }
228→  }
229→
230→  @media (prefers-contrast: more) {
231→    :root {
232→      --glow-strength: 0;
233→      --glass-strength: 0;
234→    }
235→  }
236→}
