 16→    --color-foreground: oklch(88% 0.04 145);
 17→    --color-card-foreground: oklch(88% 0.04 145);
 18→    --color-muted-foreground: oklch(55% 0.03 145);
 19→    --color-primary: oklch(68% 0.18 145);
 20→    --color-primary-foreground: oklch(10% 0.02 145);
 21→    --color-accent: oklch(68% 0.18 145);
