180→    --glow-strength: 1;
181→    --glass-strength: 1;
182→    --glow-color: oklch(72% 0.12 85);
183→    --glow-sm: 0 0 14px oklch(72% 0.12 85 / calc(0.5 * var(--glow-strength)));
184→    --glow-primary: 0 0 28px
185→      oklch(72% 0.12 85 / calc(0.75 * var(--glow-strength)));
186→    --glow-lg: 0 0 48px oklch(72% 0.12 85 / calc(1 * var(--glow-strength)));
187→    --glow-xl:
188→      0 0 72px oklch(72% 0.12 85 / calc(0.6 * var(--glow-strength))),
189→      0 0 120px oklch(72% 0.12 85 / calc(0.25 * var(--glow-strength)));
190→    --glass-shadow:
191→      inset 0 1px 0 oklch(100% 0 0 / calc(0.12 * var(--glass-strength))),
192→      0 0 20px oklch(72% 0.12 85 / calc(0.15 * var(--glow-strength)));
193→  }
194→}
