  1→/*  Builder / Foundation — light productivity theme
  2→ *
  3→ *  Applied via data-theme="tfc-builder" on <html>.
  4→ *  Overrides the default dark tokens with a warm, editorial palette
  5→ *  optimized for long authoring sessions.
  6→ *
  7→ *  Aesthetic: refined editorial — warm paper, subtle borders,
  8→ *  high-contrast slate text, calm teal accent. Think Linear meets
  9→ *  a well-typeset technical document. No glow, no glass, no spectacle.
 10→ */
 11→
 12→@layer tokens {
 13→  [data-theme="tfc-builder"] {
 14→    /* ── Surfaces ─────────────────────────────────────────── */
 15→    --color-background: oklch(97.5% 0.004 80); /* warm off-white, not stark */
 16→    --color-foreground: oklch(
 17→      22% 0.01 250
 18→    ); /* dark slate, readable for hours */
 19→    --color-card: oklch(99% 0.002 80); /* barely-there warm white */
 20→    --color-card-foreground: oklch(22% 0.01 250);
 21→    --color-popover: oklch(99% 0.002 80);
 22→    --color-popover-foreground: oklch(22% 0.01 250);
 23→    --color-muted: oklch(94% 0.005 80); /* subtle warm gray */
 24→    --color-muted-foreground: oklch(48% 0.01 250); /* secondary text */
 25→
 26→    /* ── Borders & inputs ─────────────────────────────────── */
 27→    --color-border: oklch(88% 0.008 80); /* warm light border */
 28→    --color-input: oklch(88% 0.008 80);
 29→    --color-ring: oklch(55% 0.12 230); /* focus ring — teal */
 30→
 31→    /* ── Accent: calm teal ────────────────────────────────── */
 32→    --color-primary: oklch(48% 0.12 230); /* deep teal */
 33→    --color-primary-foreground: oklch(98% 0 0); /* white on teal */
 34→    --color-accent: oklch(94% 0.015 230); /* very light teal tint */
 35→    --color-accent-foreground: oklch(30% 0.08 230); /* dark teal text */
 36→
 37→    /* ── Secondary ────────────────────────────────────────── */
 38→    --color-secondary: oklch(94% 0.005 80); /* warm neutral button bg */
 39→    --color-secondary-foreground: oklch(28% 0.01 250);
 40→
 41→    /* ── Semantic ─────────────────────────────────────────── */
 42→    --color-destructive: oklch(55% 0.22 25); /* calm red, not alarming */
 43→    --color-destructive-foreground: oklch(98% 0 0);
 44→    --color-warning: oklch(68% 0.16 70); /* warm amber */
 45→    --color-warning-foreground: oklch(25% 0.04 70);
 46→    --color-success: oklch(55% 0.16 155); /* muted green */
 47→    --color-success-foreground: oklch(98% 0 0);
 48→    --color-info: oklch(55% 0.12 230); /* matches accent */
 49→    --color-info-foreground: oklch(98% 0 0);
 50→
 51→    /* ── Shadows (lighter, warmer) ────────────────────────── */
 52→    --shadow-sm: 0 1px 2px oklch(55% 0.01 80 / 8%);
 53→    --shadow-md: 0 2px 8px oklch(55% 0.01 80 / 10%);
 54→    --shadow-lg: 0 4px 16px oklch(55% 0.01 80 / 12%);
 55→
 56→    /* ── Disable glow & glass (productivity, not spectacle) ─ */
 57→    --glow-strength: 0;
 58→    --glass-strength: 0;
 59→
 60→    /* ── Radii: slightly softer ───────────────────────────── */
 61→    --radius-sm: 4px;
 62→    --radius-md: 6px;
 63→    --radius-lg: 8px;
 64→  }
 65→}
 66→
 67→/* ── Builder-specific component overrides ───────────────────── */
 68→
 69→@layer components {
 70→  [data-theme="tfc-builder"] {
 71→    /* Sidebar: subtle separation */
 72→    & [sidebar] {
 73→      background: oklch(95.5% 0.004 80);
 74→      border-right-color: var(--color-border);
 75→    }
 76→
 77→    /* Cards: clean paper feel */
 78→    & .card {
 79→      background: var(--color-card);
 80→      border: 1px solid var(--color-border);
 81→      box-shadow: var(--shadow-sm);
 82→    }
 83→
 84→    /* Inputs: clean, no dark borders */
 85→    & .input-base {
 86→      background: var(--color-card);
 87→      border: 1px solid var(--color-border);
 88→      color: var(--color-foreground);
 89→
 90→      &:focus {
 91→        border-color: var(--color-ring);
 92→        outline: 2px solid oklch(55% 0.12 230 / 20%);
 93→        outline-offset: -1px;
 94→      }
 95→
 96→      &:disabled {
 97→        background: var(--color-muted);
 98→        color: var(--color-muted-foreground);
 99→        opacity: 0.6;
100→      }
101→    }
102→
103→    /* Select dropdowns */
104→    & select.input-base {
105→      background: var(--color-card);
106→    }
107→
108→    /* Buttons: refined, not glassy */
109→    & .btn {
110→      box-shadow: var(--shadow-sm);
111→      font-weight: 500;
112→    }
113→
114→    & .btn[data-variant="outline"] {
115→      background: var(--color-card);
116→      border-color: var(--color-border);
117→      color: var(--color-foreground);
118→
119→      &:hover {
120→        background: var(--color-muted);
121→      }
122→    }
123→
124→    /* Table rows: clean alternation via subtle borders */
125→    & table {
126→      & th {
127→        color: var(--color-muted-foreground);
128→        font-weight: 600;
129→        text-transform: uppercase;
130→        font-size: var(--font-size-xs);
131→        letter-spacing: 0.04em;
132→      }
133→
134→      & tr.border-b {
135→        border-color: var(--color-border);
136→      }
137→    }
138→
139→    /* Collapsible panels */
140→    & [class*="collapsible"] {
141→      border-color: var(--color-border);
142→    }
143→
144→    /* Badges: softer */
145→    & .badge {
146→      font-weight: 600;
147→    }
148→
149→    /* Scrollbar: light, unobtrusive */
150→    & ::-webkit-scrollbar {
151→      width: 6px;
152→    }
153→
154→    & ::-webkit-scrollbar-track {
155→      background: transparent;
156→    }
157→
158→    & ::-webkit-scrollbar-thumb {
159→      background: oklch(78% 0.005 80);
160→      border-radius: 3px;
161→
162→      &:hover {
163→        background: oklch(68% 0.005 80);
164→      }
165→    }
166→  }
167→}
