  1→/* ── TFC Home Screen — Command Center ────────────────────
  2→ *  Tactical operations aesthetic for the main menu,
  3→ *  scenario picker flow, and mode selector.
  4→ * ──────────────────────────────────────────────────────── */
  5→
  6→@layer components {
  7→  /* ── Host ─────────────────────────────────────────────── */
  8→
  9→  .home-host {
 10→    display: block;
 11→    position: relative;
 12→    min-height: 100dvh;
 13→    isolation: isolate;
 14→  }
 15→
 16→  /* ── Layout ───────────────────────────────────────────── */
 17→
 18→  .home-layout {
 19→    position: relative;
 20→    z-index: 1;
 21→    display: flex;
 22→    flex-direction: column;
 23→    align-items: center;
 24→    justify-content: center;
 25→    min-height: 100dvh;
 26→    padding: var(--spacing-xl);
 27→    gap: var(--spacing-xl);
 28→  }
 29→
 30→  /* ── Hero / System Title ──────────────────────────────── */
 31→
 32→  .home-hero {
 33→    text-align: center;
 34→    position: relative;
 35→    padding: var(--spacing-lg) var(--spacing-xl);
 36→  }
 37→
 38→  .home-hero::after {
 39→    content: "";
 40→    position: absolute;
 41→    inset: 0;
 42→    background: repeating-linear-gradient(
 43→      0deg,
 44→      transparent,
 45→      transparent 2px,
 46→      oklch(0% 0 0 / 6%) 2px,
 47→      oklch(0% 0 0 / 6%) 4px
 48→    );
 49→    pointer-events: none;
 50→    border-radius: var(--radius-sm);
