 59→    letter-spacing: 0.08em;
 60→    margin: 0 0 var(--spacing-xs);
 61→  }
 62→
 63→  .home-hero__title::before {
 64→    content: "[ ";
 65→    color: var(--color-muted-foreground);
 66→    font-weight: 400;
 67→  }
 68→
 69→  .home-hero__title::after {
 70→    content: " ]";
 71→    color: var(--color-muted-foreground);
 72→    font-weight: 400;
 73→  }
 74→
 75→  .home-hero__subtitle {
 76→    font-family: var(--font-mono);
 77→    font-size: var(--font-size-xs);
 78→    text-transform: uppercase;
 79→    letter-spacing: 0.06em;
 80→    color: var(--color-muted-foreground);
 81→    margin: 0;
