110→    text-decoration: none;
111→    color: inherit;
112→    transition:
113→      border-color var(--duration-fast),
114→      background var(--duration-fast),
115→      box-shadow var(--duration-fast);
116→    cursor: pointer;
117→  }
118→
119→  .tac-panel:hover {
