 19→
 20→@Component({
 21→  selector: "tfc-home-view",
 22→  host: { class: "home-host" },
 23→  changeDetection: ChangeDetectionStrategy.OnPush,
 24→  imports: [RouterLink, SeaBackdrop, ScenarioPicker],
 25→  template: `
 26→    <tfc-sea-backdrop />
 27→    <div class="home-layout">
