140→export class HomeView implements OnInit {
141→  private readonly http = inject(HttpClient);
142→  private readonly router = inject(Router);
143→  private readonly exerciseApi = inject(ExerciseApiService);
144→  private readonly engineApi = inject(EngineApiService);
145→  private readonly waitingRoomApi = inject(WaitingRoomApiService);
146→
147→  protected readonly lobbyData = signal<JoinableExercise[]>([]);
148→  protected readonly showPicker = signal(false);
149→  protected readonly pendingScenario = signal<ScenarioResponse | null>(null);
150→
151→  ngOnInit(): void {
152→    this.checkForJoinableExercises();
153→  }
154→
155→  protected onScenarioPicked(scenario: ScenarioResponse): void {
156→    const gameMode = scenario.content?.game_mode ?? "classic";
157→    if (gameMode === "simple_collaborative") {
158→      this.showPicker.set(false);
159→      this.pendingScenario.set(scenario);
160→      return;
161→    }
162→    this.createAndShowLobby(scenario, false);
163→  }
164→
165→  protected createMultiplayer(playerCountMode: "full" | "two_player"): void {
166→    const scenario = this.pendingScenario();
167→    if (!scenario) return;
168→    this.pendingScenario.set(null);
169→    this.createAndShowLobby(scenario, false, playerCountMode);
170→  }
171→
172→  protected createPractice(): void {
173→    const scenario = this.pendingScenario();
174→    if (!scenario) return;
175→    this.pendingScenario.set(null);
176→    const gameMode = scenario.content?.game_mode ?? "simple_collaborative";
177→
178→    this.exerciseApi
179→      .create({
180→        title: scenario.title,
181→        scenario_id: scenario.id,
182→        game_mode: gameMode,
183→        practice_mode: true,
184→      })
185→      .pipe(
186→        switchMap((exercise) =>
187→          this.waitingRoomApi.join(exercise.id, "Player", "all_roles").pipe(
188→            switchMap((participant) =>
189→              this.engineApi.start(exercise.id).pipe(
190→                switchMap(() => {
191→                  this.router.navigate(["/player"], {
192→                    queryParams: {
193→                      exerciseId: exercise.id,
194→                      participantId: participant.id,
195→                      role: "all_roles",
196→                      gameMode: "simple_collaborative",
197→                      practiceMode: true,
198→                    },
199→                  });
200→                  return [];
201→                }),
202→              ),
203→            ),
204→          ),
205→        ),
206→      )
207→      .subscribe();
208→  }
209→
210→  private createAndShowLobby(
211→    scenario: ScenarioResponse,
212→    practiceMode: boolean,
213→    playerCountMode?: "full" | "two_player",
214→  ): void {
215→    const gameMode = scenario.content?.game_mode ?? "classic";
216→    this.exerciseApi
217→      .create({
218→        title: scenario.title,
219→        scenario_id: scenario.id,
220→        game_mode: gameMode,
221→        practice_mode: practiceMode,
222→      })
223→      .subscribe({
224→        next: (exercise) => {
225→          this.router.navigate(["/waiting-room"], {
226→            queryParams: {
227→              exerciseId: exercise.id,
228→              ...(playerCountMode ? { playerCountMode } : {}),
229→            },
230→          });
231→        },
232→      });
233→  }
234→
235→  protected joinExercise(): void {
236→    this.router.navigate(["/waiting-room"], {
237→      queryParams: { browse: true },
238→    });
239→  }
240→
241→  private checkForJoinableExercises(): void {
242→    this.http
243→      .get<
244→        JoinableExercise[]
245→      >(`${environment.apiBaseUrl}/api/exercises/joinable`)
246→      .subscribe({
247→        next: (data) => this.lobbyData.set(data),
248→        error: () => this.lobbyData.set([]),
249→      });
250→  }
251→}
