543→  /* ── Stress Overlay ──────────────────────────────────── */
544→
545→  .stress-overlay-host {
546→    display: contents;
547→  }
548→  .stress-overlay {
549→    position: fixed;
550→    inset: 0;
551→    pointer-events: none;
552→    z-index: 50;
553→    background: radial-gradient(
554→      ellipse at center,
555→      transparent
556→        calc(100% - 100% * var(--stress-vignette-max) * var(--stress-severity)),
557→      oklch(0% 0 0 / calc(0.7 * var(--stress-severity))) 100%
558→    );
