572→  @media (prefers-reduced-motion: reduce) {
573→    .stress-overlay {
574→      animation: none;
575→    }
576→    body.stress-shaking {
577→      animation: none !important;
578→    }
579→  }
580→
581→  /* Shake targets the page content, not the overlay */
582→  body.stress-shaking {
583→    animation: stress-shake 0.08s linear infinite;
584→  }
585→
586→  @keyframes stress-shake {
587→    0% {
588→      translate: 0 0;
589→    }
590→    25% {
591→      translate: var(--stress-shake) calc(-1 * var(--stress-shake));
592→    }
593→    50% {
594→      translate: calc(-1 * var(--stress-shake)) var(--stress-shake);
595→    }
596→    75% {
597→      translate: var(--stress-shake) var(--stress-shake);
598→    }
599→    100% {
600→      translate: calc(-0.5 * var(--stress-shake))
601→        calc(-0.5 * var(--stress-shake));
602→    }
603→  }
604→}
